/// <summary>
/// Task 182820-CB272_SalesInvoicing-rebates
/// The <c>METRebateInvoiceController</c> class is the helper class for the associated SRS Report.
/// </summary>
public class METRebateInvoiceController extends SrsReportRunController
{
    CustInvoiceTable custInvoiceTable;
    METRebateInvoiceContract rebateInvoiceContract;
}

Method.Source:
public static METRebateInvoiceController construct()
{
    return new METRebateInvoiceController();
}

/// <summary>
/// Initailzes the controller, sets the print management, assigns parameter values and runs the SRS report.
/// </summary>
/// <param name="_args">
/// The <c>Args</c> object.
/// </param>
public static void main(Args _args)
{
    METRebateInvoiceController rebateInvoiceController = METRebateInvoiceController::construct();
    rebateInvoiceController.parmArgs(_args);

    if (_args.dataset() == tableNum(CustInvoiceTable))
    {
        CustInvoiceTable custInvoiceTable = _args.record();
        if (custInvoiceTable)
        {
            rebateInvoiceController.parmCustInvoiceTable(custInvoiceTable);
        }

    }
    else
    {
        throw error(strFmt("@SYS19306",funcName()));
    }

    rebateInvoiceController.parmShowDialog(false);
    rebateInvoiceController.parmDialogCaption("@MET:FTIRebateInvoice");
    rebateInvoiceController.startOperation();
}

/// <summary>
/// Gets or Sets CustInvoiceTable
/// </summary>
/// <param name = "_custInvoiceTable">CustInvoiceTable buffer</param>
/// <returns>CustInvoiceTable buffer</returns>
public CustInvoiceTable parmCustInvoiceTable(CustInvoiceTable _custInvoiceTable = custInvoiceTable)
{
    custInvoiceTable = _custInvoiceTable;

    return custInvoiceTable;
}

/// <summary>
/// Changes the report contract before the report is run.
/// </summary>
protected void preRunModifyContract()
{
    rebateInvoiceContract = this.parmReportContract().parmRdpContract();
    rebateInvoiceContract.parmCustInvoiceTable(this.parmCustInvoiceTable());
}
